  if(a.op==='delete_wechat_contact'){t=remoteControlFindRole(a.targetId,a.targetName,c.id);if(!t)return Object.assign(base,{ok:false,detail:'没有找到可删除的虚拟联系人'});t.deleted=true;t._delByChar=Date.now();t._deleteCount=(t._deleteCount||0)+1;friendRequestRemoveForContact(t.id);base.detail='已删除微信联系人「'+(t.remark||t.name)+'」';base.memory='删除了'+S.me.name+'的微信联系人「'+(t.remark||t.name)+'」';}
